import json, sys

data = json.load(sys.stdin)
result = json.loads(data['result'])
experiments = result['data']['experiments']

# Filter for eval experiments that are DONE/success
eval_exps = {}
for exp_id, exp in experiments.items():
    if 'eval' in exp_id.lower():
        status = exp.get('status', '')
        conclusion = exp.get('conclusion', '')
        if status == 'DONE' and conclusion == 'success':
            eval_exps[exp_id] = {
                'metrics': exp.get('metrics'),
                'spec': {k: v for k, v in (exp.get('spec') or {}).items() if k in ['model_name', 'checkpoint_source', 'eval_data']},
            }

# Sort and print
for eid in sorted(eval_exps.keys()):
    e = eval_exps[eid]
    m = e['metrics'] or {}
    print(f'=== {eid} ===')
    print(f'  metrics: {json.dumps(m)}')
    print(f'  spec: {json.dumps(e[\"spec\"])}')
    print()
" 2>&1

